"""Red-team harness for design-after-midpoint-review.md section 2.2.

Two engines over the SAME hazard model:

  EXACT   one variable per claim with K+1 states (the first-passage epoch, or
          "never"), solved by variable elimination.  This is review2's Plan A and
          it is the ground truth the design measures itself against.

  BINARY  the design under attack.  ONE forward pass gives every claim's
          arrival-time distribution under the PRIOR; each child's yes/no table is
          its hazard integral averaged over its parents' arrival distributions
          (parents treated as independent); the yes/no network is then solved
          exactly.  `do` re-runs the forward pass with the claim pinned.
          `observe` multiplies in an indicator and renormalises -- the tables are
          NOT rebuilt, which is the thing this harness is here to measure.

The analyst's scripts only ever used step-shaped arrows.  This one carries all
three shapes the product actually has (step / impulse with a half-life / ramp),
because timing error is exactly where an impulse lives.
"""

from __future__ import annotations

import itertools
import math
from dataclasses import dataclass, field

import numpy as np

T = 60.0  # the window, days


# --------------------------------------------------------------------- the map


@dataclass
class Arrow:
    src: str
    q1: float  # P(target by its deadline | src happened on day 0)
    lag: float = 0.0
    shape: str = "step"  # step | impulse | ramp
    half_life: float = 10.0  # the impulse's half-life, or the ramp's length


@dataclass
class Claim:
    D: float  # resolve-by day
    q0: float  # P(true by D) with no modelled cause active -- the leak
    parents: list[Arrow] = field(default_factory=list)


Map = dict[str, Claim]


# ------------------------------------------------------------------ the hazard


def shape_of(kind: str, u: np.ndarray, half_life: float) -> np.ndarray:
    """How much of full strength the arrow carries `u` days after it switched on."""
    on = u >= 0.0
    if kind == "step":
        return np.where(on, 1.0, 0.0)
    if kind == "impulse":
        return np.where(on, 0.5 ** (np.clip(u, 0.0, None) / max(half_life, 1e-9)), 0.0)
    if kind == "ramp":
        return np.where(on, np.clip(np.clip(u, 0.0, None) / max(half_life, 1e-9), 0.0, 1.0), 0.0)
    raise ValueError(kind)


def integrated(l0: float, ws, arrows, ons, D: float, K: int, sub: int = 8) -> np.ndarray:
    """Integrated hazard per epoch, for a claim with rate l0*exp(sum w_j s_j(t)).

    Each epoch is split into `sub` slices so a decaying impulse is integrated
    honestly rather than sampled at one point.  Nothing accrues past the deadline.
    """
    edges = np.linspace(0.0, T, K + 1)
    lo, hi = edges[:-1], np.minimum(edges[1:], D)
    width = np.clip(hi - lo, 0.0, None)
    mids = lo[:, None] + (np.arange(sub)[None, :] + 0.5) * (width[:, None] / sub)
    logmul = np.zeros((K, sub))
    for w, a, on in zip(ws, arrows, ons):
        if not np.isfinite(on):
            continue
        logmul += w * shape_of(a.shape, mids - (on + a.lag), a.half_life)
    return l0 * np.exp(logmul).mean(axis=1) * width


def pmf(l0: float, ws, arrows, ons, D: float, K: int) -> np.ndarray:
    """P(tau = epoch k) for k=0..K-1, then P(never) in the last slot."""
    H = integrated(l0, ws, arrows, ons, D, K)
    surv = np.exp(-np.concatenate([[0.0], np.cumsum(H)]))
    return np.append(surv[:-1] - surv[1:], surv[-1])


def calibrate(claim: Claim, K: int) -> tuple[float, list[float]]:
    """lambda0 from q0; one weight per arrow so a cause on day 0 reproduces its q1.

    Closed form for a step; bisection otherwise, which is what a real
    implementation would have to do too.
    """
    l0 = -math.log1p(-claim.q0) / claim.D
    ws: list[float] = []
    for a in claim.parents:
        if a.shape == "step" and a.lag < claim.D:
            l1 = (-math.log1p(-a.q1) - l0 * a.lag) / (claim.D - a.lag)
            ws.append(math.log(max(l1, 1e-12) / l0))
            continue

        def reached(w: float) -> float:
            return 1.0 - pmf(l0, [w], [a], [0.0], claim.D, K)[-1]

        lo, hi = -40.0, 40.0
        target = a.q1
        if reached(hi) < target:
            ws.append(hi)
            continue
        if reached(lo) > target:
            ws.append(lo)
            continue
        for _ in range(90):
            mid = 0.5 * (lo + hi)
            if reached(mid) < target:
                lo = mid
            else:
                hi = mid
        ws.append(0.5 * (lo + hi))
    return l0, ws


# --------------------------------------------- EXACT: variable elimination over times


def _order(m: Map) -> list[str]:
    seen: list[str] = []
    while len(seen) < len(m):
        for name, c in m.items():
            if name in seen:
                continue
            if all(a.src in seen for a in c.parents):
                seen.append(name)
                break
        else:
            raise ValueError("cycle")
    return seen


def exact_over_times(m: Map, K: int, do=None, observe=None) -> dict[str, float]:
    """Plan A.  The joint over first-passage epochs, marginalised one claim at a time."""
    names = _order(m)
    days = np.append(np.linspace(0.0, T, K + 1)[1:], np.inf)
    NEVER = K
    factors: list[tuple[tuple[str, ...], np.ndarray]] = []
    for name in names:
        c = m[name]
        l0, ws = calibrate(c, K)
        pa = [a.src for a in c.parents]
        if do is not None and name in do:
            f = np.zeros(K + 1)
            f[0 if do[name] else NEVER] = 1.0
            factors.append(((name,), f))
            continue
        if not pa:
            factors.append(((name,), pmf(l0, [], [], [], c.D, K)))
            continue
        block = np.zeros((K + 1,) * (len(pa) + 1))
        for combo in itertools.product(range(K + 1), repeat=len(pa)):
            block[combo] = pmf(l0, ws, c.parents, [days[i] for i in combo], c.D, K)
        factors.append((tuple(pa) + (name,), block))
    if observe:
        for name, value in observe.items():
            ind = np.zeros(K + 1)
            if value:
                ind[:NEVER] = 1.0
            else:
                ind[NEVER] = 1.0
            factors.append(((name,), ind))
    return {n: _ve(factors, n, names, K) for n in names}


def _ve(factors, target: str, names, K: int) -> float:
    fs = [(list(v), a.copy()) for v, a in factors]
    for name in names:
        if name == target:
            continue
        touching = [f for f in fs if name in f[0]]
        fs = [f for f in fs if name not in f[0]]
        if not touching:
            continue
        allv: list[str] = []
        for v, _ in touching:
            for x in v:
                if x not in allv:
                    allv.append(x)
        acc = np.ones((K + 1,) * len(allv))
        for v, a in touching:
            idx = [allv.index(x) for x in v]
            acc = acc * np.moveaxis(
                a.reshape(a.shape + (1,) * (len(allv) - len(v))),
                range(len(v)),
                idx,
            )
        ax = allv.index(name)
        acc = acc.sum(axis=ax)
        rest = [x for x in allv if x != name]
        fs.append((rest, acc))
    acc = np.ones(K + 1)
    scalar = 1.0
    for v, a in fs:
        if v == [target]:
            acc = acc * a
        elif not v:
            scalar *= float(a)
        else:
            raise AssertionError(v)
    acc = acc / acc.sum()
    return float(1.0 - acc[K])


# ----------------------------------------- BINARY: the design under attack


def binary(m: Map, K: int, do=None, observe=None, *, rebuild_under_evidence=False):
    """One forward timing pass under the prior, then an exact solve over truths."""
    names = _order(m)
    days = np.append(np.linspace(0.0, T, K + 1)[1:], np.inf)
    arrival: dict[str, np.ndarray] = {}  # P(tau = k), last slot = never
    cpt: dict[str, np.ndarray] = {}

    for name in names:
        c = m[name]
        l0, ws = calibrate(c, K)
        pa = [a.src for a in c.parents]
        k = len(pa)

        # --- the yes/no table: the hazard integral averaged over parents' arrivals
        table = np.zeros((2,) * k) if k else np.zeros(())
        for combo in itertools.product((0, 1), repeat=k):
            grids, probs = [], []
            for j, src in enumerate(pa):
                if combo[j] == 0:
                    grids.append(np.array([np.inf]))
                    probs.append(np.array([1.0]))
                else:
                    pm = arrival[src][:K]
                    tot = pm.sum()
                    grids.append(days[:K])
                    probs.append(pm / tot if tot > 1e-15 else np.full(K, 1.0 / K))
            tot = 0.0
            if k:
                for cell in itertools.product(*[range(len(g)) for g in grids]):
                    w = float(np.prod([probs[j][cell[j]] for j in range(k)]))
                    if w < 1e-10:
                        continue
                    ons = [grids[j][cell[j]] for j in range(k)]
                    tot += w * (1.0 - pmf(l0, ws, c.parents, ons, c.D, K)[-1])
            else:
                tot = 1.0 - pmf(l0, [], [], [], c.D, K)[-1]
            table[combo] = tot
        cpt[name] = table

        # --- the forward pass: this claim's own arrival distribution
        if do is not None and name in do:
            f = np.zeros(K + 1)
            f[0 if do[name] else K] = 1.0
            arrival[name] = f
            continue
        acc = np.zeros(K + 1)
        for combo in itertools.product((0, 1), repeat=k):
            wcombo = 1.0
            grids, probs = [], []
            for j, src in enumerate(pa):
                p_src = 1.0 - arrival[src][K]
                wcombo *= p_src if combo[j] else (1.0 - p_src)
                if combo[j] == 0:
                    grids.append(np.array([np.inf]))
                    probs.append(np.array([1.0]))
                else:
                    pm = arrival[src][:K]
                    tot = pm.sum()
                    grids.append(days[:K])
                    probs.append(pm / tot if tot > 1e-15 else np.full(K, 1.0 / K))
            if wcombo < 1e-10:
                continue
            if k:
                for cell in itertools.product(*[range(len(g)) for g in grids]):
                    w = float(np.prod([probs[j][cell[j]] for j in range(k)]))
                    if w < 1e-10:
                        continue
                    ons = [grids[j][cell[j]] for j in range(k)]
                    acc += wcombo * w * pmf(l0, ws, c.parents, ons, c.D, K)
            else:
                acc += wcombo * pmf(l0, [], [], [], c.D, K)
        arrival[name] = acc / acc.sum()

    return _solve_truths(m, names, cpt, do, observe)


def _solve_truths(m, names, cpt, do, observe) -> dict[str, float]:
    n = len(names)
    states = list(itertools.product((0, 1), repeat=n))
    probs = np.ones(len(states))
    for s, st in enumerate(states):
        val = dict(zip(names, st))
        p = 1.0
        for name in names:
            if do is not None and name in do:
                p *= 1.0 if val[name] == int(do[name]) else 0.0
                continue
            pa = [a.src for a in m[name].parents]
            row = cpt[name]
            if pa:
                row = row[tuple(val[x] for x in pa)]
            q = float(row)
            p *= q if val[name] else 1.0 - q
        probs[s] = p
    if observe:
        mask = np.array(
            [all(st[names.index(k)] == int(v) for k, v in observe.items()) for st in states]
        )
        probs = probs * mask
    if probs.sum() <= 0:
        return None
    probs = probs / probs.sum()
    return {
        name: float(sum(p for st, p in zip(states, probs) if st[names.index(name)] == 1))
        for name in names
    }


def worst_gap(m: Map, K: int, queries) -> tuple[float, tuple]:
    worst, where = 0.0, None
    for label, do, obs in queries:
        a = exact_over_times(m, K, do, obs)
        b = binary(m, K, do, obs)
        if b is None:
            continue
        for name in a:
            d = abs(a[name] - b[name])
            if d > worst:
                worst, where = d, (label, name, a[name], b[name])
    return worst, where
